/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }
  if (org.archivedAt !== null) throw new AlreadyArchivedError("Organization", input.orgId);
  const deleted = await orgRepo.archiveOrg(input.orgId);
  await emit("organization.deleted", { ...envelope(input.orgId, actor.userId), slug: org.slug });
  return deleted;
}

/** Restore a deleted organization during its fixed recovery window. */
export async function restoreOrganization(userId: UserId, orgId: OrgId): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.archivedAt !== null || member.status !== "active") throw new NotFoundError("Organization", orgId);
  if (org.archivedAt === null) return org;
  const deadline = new Date(new Date(org.archivedAt).getTime() + DELETED_WORKSPACE_RETENTION_DAYS * 24 * 60 * 60 * 1000);
  if (Date.now() >= deadline.getTime()) throw new NotFoundError("Organization", orgId);
  const actor: Actor = { orgId, userId, role: member.role, isPlatformStaff: false };
  assertCan(actor, "org:restore", orgResource(orgId));
  if (org.archivedAt === null) return org;
  const restored = await orgRepo.restoreOrg(orgId);
  await emit("organization.restored", { ...envelope(orgId, userId), slug: org.slug });
  return restored;
}

